// Front-end API code generated from the back end's OpenAPI schema
// (Foundation Fixes fix 2). Run `npm run generate:api` after
// `python tools/export_openapi.py`; never edit lib/generated by hand.
import {defineConfig} from '@hey-api/openapi-ts';

export default defineConfig({
  input: './openapi.json',
  output: {path: './lib/generated', postProcess: ['prettier']},
  // The operator console's routes (/api/console, ADR-0003) are in the API
  // schema, but this front end never calls them: the console has its own
  // framework-free UI, served by the backend at /console (ADR-0003, D5).
  // Its 65 operations are left out of the generated client, and the schemas
  // only they use with them (unreferenced schemas are dropped by default).
  // A filter between slashes is a regular expression over "METHOD /path"
  // (@hey-api/shared createFiltersSetAndRegExps, createOperationKey).
  parser: {filters: {operations: {exclude: ['/^[A-Z]+ \\/api\\/console\\//']}}},
  plugins: [
    '@hey-api/client-fetch',
    '@hey-api/typescript',
    // The app uses Zod 3 (package.json); checked 2026-10-01 that the plugin
    // supports it via compatibilityVersion. The database keeps UTC times
    // without an offset (backend app/core/time.py), so those must pass too.
    // (The response models declare their times with a pattern that allows
    // both, Timestamp in backend/app/schemas/responses.py; this covers any
    // "date-time" format the schema may still carry.)
    {name: 'zod', compatibilityVersion: 3, dates: {local: true, offset: true}},
    {name: '@hey-api/sdk', validator: true},
    '@tanstack/react-query',
  ],
});
